import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 20 + 15 + 200 + 15 + 200 + 15 + 25 - (15 + 15 + 15);

const COLORS = {
  orange: "#FF6B35",
  orangeLight: "#FF9A6C",
  green: "#00C851",
  white: "#FFFFFF",
  offWhite: "#F0EDE8",
  muted: "#A89F98",
  bg: "#0A0A0A",
  dark: "#111111",
};

const TRANSITION = 15;

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── Scene 1: Hook ───────────────────────────────────────────────────────────
const SceneHook: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const glowPulse = interpolate(frame, [0, 50, 100, 150, 200], [0.4, 1, 0.4, 1, 0.4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const logoProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const line1Progress = spring({ frame, fps, delay: 20, config: { damping: 200 } });
  const line2Progress = spring({ frame, fps, delay: 45, config: { damping: 200 } });
  const tagProgress = spring({ frame, fps, delay: 70, config: { damping: 200 } });
  const arrowProgress = spring({ frame, fps, delay: 95, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      {/* Radial glow */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 1400px 900px at 50% 50%, rgba(255,107,53,${0.12 * glowPulse}) 0%, transparent 70%)`,
        }}
      />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 160,
          gap: 60,
        }}
      >
        {/* Apify Logo */}
        <div
          style={{
            opacity: logoProgress,
            transform: `scale(${interpolate(logoProgress, [0, 1], [0.7, 1])})`,
          }}
        >
          <Img
            src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
            style={{ width: 520, height: "auto" }}
          />
        </div>

        {/* Divider line */}
        <div
          style={{
            width: interpolate(line1Progress, [0, 1], [0, 700]),
            height: 2,
            background: `linear-gradient(90deg, transparent, ${COLORS.orange}, transparent)`,
            borderRadius: 1,
          }}
        />

        {/* Main headline */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 32,
          }}
        >
          <div
            style={{
              opacity: line2Progress,
              transform: `translateY(${interpolate(line2Progress, [0, 1], [80, 0])}px)`,
              fontSize: 148,
              fontWeight: 800,
              color: COLORS.white,
              letterSpacing: "-0.03em",
              lineHeight: 1,
              textAlign: "center",
            }}
          >
            Scrape Smarter.
          </div>

          <div
            style={{
              opacity: tagProgress,
              transform: `translateY(${interpolate(tagProgress, [0, 1], [60, 0])}px)`,
              fontSize: 148,
              fontWeight: 800,
              background: `linear-gradient(135deg, ${COLORS.orange}, ${COLORS.orangeLight})`,
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              letterSpacing: "-0.03em",
              lineHeight: 1,
              textAlign: "center",
            }}
          >
            Not Harder.
          </div>
        </div>

        {/* Arrow + CTA hint */}
        <div
          style={{
            opacity: arrowProgress,
            transform: `translateY(${interpolate(arrowProgress, [0, 1], [40, 0])}px)`,
            display: "flex",
            alignItems: "center",
            gap: 20,
          }}
        >
          <svg width="52" height="52" viewBox="0 0 52 52" fill="none">
            <path
              d="M26 8L26 44M26 44L14 32M26 44L38 32"
              stroke={COLORS.orange}
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
          <span
            style={{
              fontSize: 42,
              fontWeight: 600,
              color: COLORS.muted,
              letterSpacing: "0.05em",
            }}
          >
            keep watching
          </span>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─── Scene 2: Features ────────────────────────────────────────────────────────
const FEATURES = [
  { icon: "🕷️", label: "Web Scraping", desc: "Extract any data from any website" },
  { icon: "🤖", label: "AI Agents", desc: "Automate complex workflows at scale" },
  { icon: "📊", label: "Ready-to-use", desc: "3,000+ pre-built Actors available" },
];

const FeatureCard: React.FC<{
  feature: (typeof FEATURES)[number];
  delay: number;
}> = ({ feature, delay }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const progress = spring({ frame, fps, delay, config: { damping: 200 } });

  return (
    <div
      style={{
        opacity: progress,
        transform: `translateY(${interpolate(progress, [0, 1], [80, 0])}px)`,
        backgroundColor: "rgba(255,255,255,0.04)",
        border: "2px solid rgba(255,107,53,0.25)",
        borderRadius: 32,
        padding: "52px 60px",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 24,
        width: 580,
        textAlign: "center",
      }}
    >
      <span style={{ fontSize: 96 }}>{feature.icon}</span>
      <div
        style={{
          fontSize: 52,
          fontWeight: 800,
          color: COLORS.white,
          letterSpacing: "-0.02em",
        }}
      >
        {feature.label}
      </div>
      <div
        style={{
          fontSize: 36,
          fontWeight: 500,
          color: COLORS.muted,
          lineHeight: 1.4,
        }}
      >
        {feature.desc}
      </div>
    </div>
  );
};

const SceneFeatures: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const titleProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const subtitleProgress = spring({ frame, fps, delay: 20, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      <AbsoluteFill
        style={{
          background: "radial-gradient(ellipse 2000px 1200px at 50% 50%, rgba(255,107,53,0.07) 0%, transparent 70%)",
        }}
      />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 140,
          gap: 72,
        }}
      >
        {/* Header */}
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 24 }}>
          <div
            style={{
              opacity: titleProgress,
              transform: `translateY(${interpolate(titleProgress, [0, 1], [60, 0])}px)`,
              fontSize: 100,
              fontWeight: 800,
              color: COLORS.white,
              letterSpacing: "-0.03em",
              textAlign: "center",
            }}
          >
            Everything you need to
          </div>
          <div
            style={{
              opacity: subtitleProgress,
              transform: `translateY(${interpolate(subtitleProgress, [0, 1], [50, 0])}px)`,
              fontSize: 100,
              fontWeight: 800,
              background: `linear-gradient(135deg, ${COLORS.orange}, ${COLORS.orangeLight})`,
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              letterSpacing: "-0.03em",
              textAlign: "center",
            }}
          >
            collect web data.
          </div>
        </div>

        {/* Feature cards */}
        <div style={{ display: "flex", flexDirection: "row", gap: 48, alignItems: "stretch" }}>
          {FEATURES.map((feat, i) => (
            <FeatureCard key={i} feature={feat} delay={50 + i * 20} />
          ))}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─── Scene 3: CTA ─────────────────────────────────────────────────────────────
const SceneCTA: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgGlow = interpolate(frame, [0, 100, 200], [0.6, 1, 0.6], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const logoProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });
  const freeProgress = spring({ frame, fps, delay: 20, config: { damping: 200 } });
  const trialProgress = spring({ frame, fps, delay: 38, config: { damping: 200 } });
  const inBioProgress = spring({ frame, fps, delay: 60, config: { damping: 200 } });
  const badgeProgress = spring({ frame, fps, delay: 85, config: { damping: 200 } });
  const subProgress = spring({ frame, fps, delay: 105, config: { damping: 200 } });

  // Pulsing badge scale
  const badgePulse = interpolate(
    Math.sin((frame / 25) * Math.PI * 2),
    [-1, 1],
    [0.97, 1.03]
  );

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background />

      {/* Dramatic glow */}
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 1800px 1100px at 50% 55%, rgba(255,107,53,${0.18 * bgGlow}) 0%, rgba(255,107,53,${0.06 * bgGlow}) 40%, transparent 70%)`,
        }}
      />

      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          paddingBottom: 100,
          gap: 64,
        }}
      >
        {/* Logo */}
        <div
          style={{
            opacity: logoProgress,
            transform: `scale(${interpolate(logoProgress, [0, 1], [0.8, 1])})`,
          }}
        >
          <Img
            src={staticFile("assets/apify/Apify Logo white Wordmark.svg")}
            style={{ width: 420, height: "auto" }}
          />
        </div>

        {/* Main CTA text */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 16,
          }}
        >
          <div
            style={{
              opacity: freeProgress,
              transform: `scale(${interpolate(freeProgress, [0, 1], [0.6, 1])}) translateY(${interpolate(freeProgress, [0, 1], [60, 0])}px)`,
              fontSize: 220,
              fontWeight: 900,
              background: `linear-gradient(135deg, ${COLORS.orange} 0%, ${COLORS.orangeLight} 50%, #FFD700 100%)`,
              WebkitBackgroundClip: "text",
              WebkitTextFillColor: "transparent",
              letterSpacing: "-0.04em",
              lineHeight: 0.9,
              textAlign: "center",
            }}
          >
            FREE
          </div>

          <div
            style={{
              opacity: trialProgress,
              transform: `translateY(${interpolate(trialProgress, [0, 1], [50, 0])}px)`,
              fontSize: 120,
              fontWeight: 800,
              color: COLORS.white,
              letterSpacing: "-0.03em",
              textAlign: "center",
            }}
          >
            Apify Trial
          </div>
        </div>

        {/* "in bio" pill */}
        <div
          style={{
            opacity: inBioProgress,
            transform: `translateY(${interpolate(inBioProgress, [0, 1], [40, 0])}px)`,
            display: "flex",
            alignItems: "center",
            gap: 24,
          }}
        >
          {/* Animated arrow */}
          <svg
            width="64"
            height="64"
            viewBox="0 0 64 64"
            fill="none"
            style={{
              opacity: inBioProgress,
              transform: `rotate(${interpolate(inBioProgress, [0, 1], [-90, 0])}deg)`,
            }}
          >
            <path
              d="M32 8L56 32L32 56M8 32H56"
              stroke={COLORS.orange}
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>

          <div
            style={{
              backgroundColor: "rgba(255,107,53,0.12)",
              border: `3px solid ${COLORS.orange}`,
              borderRadius: 60,
              padding: "28px 80px",
              fontSize: 80,
              fontWeight: 800,
              color: COLORS.white,
              letterSpacing: "0.04em",
            }}
          >
            LINK IN BIO
          </div>

          <svg
            width="64"
            height="64"
            viewBox="0 0 64 64"
            fill="none"
            style={{
              opacity: inBioProgress,
              transform: `rotate(${interpolate(inBioProgress, [0, 1], [90, 0])}deg)`,
            }}
          >
            <path
              d="M32 8L8 32L32 56M56 32H8"
              stroke={COLORS.orange}
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </div>

        {/* "No credit card required" badge */}
        <div
          style={{
            opacity: badgeProgress,
            transform: `scale(${interpolate(badgeProgress, [0, 1], [0.7, 1]) * badgePulse})`,
            backgroundColor: "rgba(0,200,81,0.1)",
            border: `2px solid rgba(0,200,81,0.4)`,
            borderRadius: 20,
            padding: "22px 60px",
            display: "flex",
            alignItems: "center",
            gap: 20,
          }}
        >
          <svg width="44" height="44" viewBox="0 0 44 44" fill="none">
            <path
              d="M8 22L18 32L36 14"
              stroke={COLORS.green}
              strokeWidth="3.5"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
          <span
            style={{
              fontSize: 44,
              fontWeight: 700,
              color: COLORS.green,
              letterSpacing: "0.08em",
            }}
          >
            NO CREDIT CARD REQUIRED
          </span>
        </div>

        {/* Sub line */}
        <div
          style={{
            opacity: subProgress,
            transform: `translateY(${interpolate(subProgress, [0, 1], [30, 0])}px)`,
            fontSize: 38,
            fontWeight: 500,
            color: COLORS.muted,
            textAlign: "center",
            letterSpacing: "0.02em",
          }}
        >
          Start scraping the web in minutes · apify.com
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

// ─── Total duration calculation ───────────────────────────────────────────────
// Sequences: BlackScreen(20) + SceneHook(200) + SceneFeatures(200) + SceneCTA(200) + BlackScreen(25)
// Transitions: fade(20) + fade(TRANSITION) + fade(TRANSITION) + fade(TRANSITION)
// Total = 20 + 200 + 200 + 200 + 25 - (20 + 15 + 15 + 15) = 645 - 65 = 580

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: 20 })}
      />

      {/* Scene 1: Hook */}
      <TransitionSeries.Sequence durationInFrames={200 + TRANSITION}>
        <SceneHook />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 2: Features */}
      <TransitionSeries.Sequence durationInFrames={200 + TRANSITION}>
        <SceneFeatures />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Scene 3: CTA */}
      <TransitionSeries.Sequence durationInFrames={200 + TRANSITION}>
        <SceneCTA />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
